```js
const jobs = new Map(); // job_id -> 'running' | 'cancelled'

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job. Returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job. Rejects missing jobs or already-cancelled jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job to cancel.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

function requireJobId(args) {
  if (args == null || typeof args !== 'object') {
    throw new Error('Arguments must be an object');
  }
  const { job_id } = args;
  if (typeof job_id !== 'string' || job_id.length === 0) {
    throw new Error('job_id is required and must be a non-empty string');
  }
  return job_id;
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'start_job': {
      const job_id = requireJobId(args);
      if (jobs.get(job_id) === 'running') {
        throw new Error(`Job ${job_id} is already active`);
      }
      jobs.set(job_id, 'running');
      return textResult(`Job ${job_id} is running`);
    }
    case 'cancel_job': {
      const job_id = requireJobId(args);
      const status = jobs.get(job_id);
      if (status === undefined) {
        throw new Error(`Job ${job_id} not found`);
      }
      if (status === 'cancelled') {
        throw new Error(`Job ${job_id} is already cancelled`);
      }
      jobs.set(job_id, 'cancelled');
      return textResult(`Job ${job_id} cancelled`);
    }
    default:
      throw new Error(`Unknown tool: ${name}`);
  }
}
```

The test checks `/cancelled/` — `Job j1 cancelled` matches. Good.

